import {holeTargets,progressAt,delayWindow,delayIncident,roundSchedule} from './traffic-model.js';
import {mapPoints} from './bandon-model.js';
export const clock=n=>`${String(Math.floor(n/60)%24).padStart(2,'0')}:${String(Math.floor(n%60)).padStart(2,'0')}`;
export function situation(minutes,choice='auto'){return choice==='auto'?(delayIncident(minutes).active?'queue':'normal'):choice;}
export function groupsAt(minutes,choice='auto',target=245,configuredTargets){const targets=configuredTargets||holeTargets([],target),incident=delayIncident(minutes,choice,targets),state=choice==='auto'?(incident.active?'queue':'normal'):choice,groups=[];for(const scheduledGroup of roundSchedule(targets,choice,minutes)){const {id,cells}=scheduledGroup,elapsed=Math.max(0,minutes+(8-id)*10),scheduled=minutes<(id-8)*10;let index=cells.findIndex(c=>minutes<c.exit);const completed=index<0;if(completed)index=17;const cell=cells[index];let fraction=minutes<cell.approach?Math.max(0,(minutes-cell.entry)/targets[index]):minutes<cell.release?.65:.65+(minutes-cell.release)/targets[index];let progress=scheduled?.02:index+fraction;if(state==='gap'&&id===8)progress=Math.max(.04,progress-.45);if(state==='stale'&&id===8)progress=.06;const desired=progress;if(groups.length&&!scheduled&&!groups.at(-1).completed)progress=Math.min(progress,groups.at(-1).progress-.12);progress=Math.min(17.98,Math.max(.02,progress));const hole=Math.floor(progress)+1,waiting=!completed&&!scheduled&&!((state==='stale')&&id===8)&&((cell.delay>.05&&minutes>=cell.approach&&minutes<cell.release)||progress<desired-.02),knownIncident=incident.active?incident:cell.delay>.05?{...incident,clearing:minutes>=incident.clearAt}:null;const trafficDelay=Math.max(0,cell.entry-((id-8)*10)-targets.slice(0,index).reduce((a,b)=>a+b,0));const gapSustained=state==='gap'&&id===8&&minutes>=5&&Array.from({length:6},(_,i)=>minutes-i).every(t=>progressAt(t+10,targets)-Math.max(.04,progressAt(t,targets)-.45)>.9);groups.push({id,gapSustained,completed,finishAt:cells[17].exit,trafficDelay,hole,fraction:progress%1,progress,stale:state==='stale'&&id===8,status:state,waiting,delayMinutes:cell.delay,sourceDelay:id===7&&hole===5&&(choice==='auto'||choice==='queue')&&minutes>cell.normalExit,holeTarget:targets[hole-1],holeElapsed:Math.max(0,minutes-cell.entry),elapsed,incident:knownIncident});}return groups;}

export function boundsForHole(hole){const col=(hole-1)%6,row=Math.floor((hole-1)/6);return [[-row*950, col*590],[800-row*950,450+col*590]];}
export function atlasPosition(group){const bounds=boundsForHole(group.hole),p=mapPoints(group.hole,4);const x=p.tee.x+(p.pin.x-p.tee.x)*group.fraction,y=p.tee.y+(p.pin.y-p.tee.y)*group.fraction;return [bounds[0][0]+800-y,bounds[0][1]+x];}
export function roundBrief(minutes,choice='auto'){const state=situation(minutes,choice);return {state,title:{normal:'Your group is on pace',queue:'Traffic ahead · waiting is okay',gap:'A gap is opening ahead',stale:'Your group’s tracking is paused'}[state],message:{normal:'Keep comfortable contact with the group ahead. Tap any group to see its progress.',queue:'A queue is forming in this demo. Your finish estimate has moved later; no pace penalty applies.',gap:'There is room ahead in this scenario. Please keep pace when safe.',stale:'The demo marker is frozen at its last observation. No pace warning is issued.'}[state],finish:clock(510+245+(state==='queue'?18:state==='gap'?10:0))};}
